  if c=="["then
   while text:sub(p,p)~="]"do value[#value+1]=take()end;p=p+1
  elseif c=="{"then
   while text:sub(p,p)~="}"do local key=take();value[key]=take()end;p=p+1
  else error("Invalid profession learning codec")end
